+++ b/training/level-1/L1-035-config-merge/safeConfigMerge.mjs
@@ -0,0 +1,69 @@
+import { isPlain } from './helpers.js';
+
+function validateValue(value) {
+  if (value === undefined || typeof value === 'function' || typeof value === 'symbol' || typeof value === 'bigint') {
+    throw new TypeError('Invalid value type');
+  }
+  if (typeof value === 'number' && (!Number.isFinite(value))) {
+    throw new RangeError('Non-finite number value');
+  }
+}
+
+function cloneValue(value) {
+  if (value === null || !isPlain(value)) return value;
+  if (Array.isArray(value)) {
+    return value.map(cloneValue);
+  }
+  const cloned = Object.create(null);
+  const keys = Object.keys(value).sort();
+  for (const key of keys) {
+    cloned[key] = cloneValue(value[key]);
+  }
+  return cloned;
+}
+
+function mergeObjects(base, overlay) {
+  if (!isPlain(base) || !isPlain(overlay)) {
+    throw new RangeError('Both inputs must be plain objects');
+  }
+
+  const result = Object.create(null);
+  const allKeys = [...new Set([...Object.keys(base), ...Object.keys(overlay)])].sort();
+
+  for (const key of allKeys) {
+    if (key === '__proto__' || key === 'prototype' || key === 'constructor') {
+      throw new RangeError('Dangerous key detected');
+    }
+
+    const baseValue = base[key];
+    const overlayValue = overlay[key];
+
+    if (isPlain(baseValue) && isPlain(overlayValue)) {
+      result[key] = mergeObjects(baseValue, overlayValue);
+    } else if (overlayValue !== undefined) {
+      result[key] = cloneValue(overlayValue);
+    } else {
+      result[key] = cloneValue(baseValue);
+    }
+  }
+
+  return result;
+}
+
+function deepFreeze(obj) {
+  if (obj === null || typeof obj !== 'object') return obj;
+  Object.freeze(obj);
+  for (const key of Object.keys(obj)) {
+    deepFreeze(obj[key]);
+  }
+  return obj;
+}
+
+export function safeConfigMerge(base, overlay) {
+  if (!isPlain(base) || !isPlain(overlay)) {
+    throw new RangeError('Both inputs must be plain objects');
+  }
+
+  const merged = mergeObjects(base, overlay);
+  return deepFreeze(merged);
+}

